/**
 * Brand marks for the technology wall in the Capabilities section.
 *
 * GENERATED - do not hand-edit. Path data comes from the `simple-icons` set
 * (https://simpleicons.org, CC0-1.0); only the marks actually used are vendored
 * here, so the multi-megabyte upstream package stays out of the client build.
 *
 * Three entries are sourced elsewhere and are noted where they appear: Azure
 * (dropped from the upstream release), Matplotlib (no upstream mark) and
 * SureCart (official brand asset, trademark of SureCart).
 *
 * Each entry keeps its official brand hex so the tile can render the logo in
 * its real colour.
 */
export type BrandMark = {
  /** Official product name, as published by the brand. */
  title: string;
  /** Official brand colour, upper-case hex without the leading hash. */
  hex: string;
  /** Non-standard artboard. Defaults to the 24x24 grid simple-icons uses. */
  viewBox?: string;
  /** Winding rule for marks whose inner shapes are knocked out of a solid. */
  fillRule?: "evenodd" | "nonzero";
  /** Single 24x24 path, tinted with `hex` by the tile. */
  path?: string;
  /** Full-colour inline markup, for logos that are not one flat shape. */
  svg?: string;
};

